const PORT = Number(Bun.env.PORT || 3000);
const COOKIE_NAME = "__Host-mfa_session";
const IDLE_MS = 20 * 60 * 1000;
const ABSOLUTE_MS = 8 * 60 * 60 * 1000;
const LOCK_MS = 15 * 60 * 1000;
const MAX_FAILURES = 5;
