  "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "no-referrer",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Cache-Control": "no-store, private",
};

type Session = {
  id: string;
  csrf: string;
  accountId?: string;
  identityVerified: boolean;
  createdAt: number;
  lastSeen: number;
  failedLogin: number;
  failedIdentity: number;
  failedMfa: number;
  lockedUntil: number;
};

type Encrypted = { iv: string; ciphertext: string };
type PendingProvision = {
  secret: Encrypted;
  expiresAt: number;
  used: boolean;
};
type Account = {
  id: string;
  email: string;
  passwordHash: string;
  phone: string;
  identityCode?: string;
  identityExpiresAt?: number;
  identityUsed?: boolean;
  mfaSecret?: Encrypted;
  pending?: PendingProvision;
  backupCodes: { digest: string; used: boolean }[];
  mfaEnabled: boolean;
  mfaLockedUntil: number;
};

const sessions = new Map<string, Session>();
const accounts = new Map<string, Account>();
const encryptionKeyPromise = crypto.subtle.generateKey(
  { name: "AES-GCM", length: 256 },
  false,
  ["encrypt", "decrypt"],
);
const recoveryPepper = randomText(32);
const PASSWORD_HASH = await sha256("BankPass!9");

/* Security Evaluation 3: only encrypted secrets / hashes are retained in memory. */
accounts.set("acct_marcus", {
  id: "acct_marcus",
  email: "marcus@example.test",
  passwordHash: PASSWORD_HASH,
  phone: "+15551234567",
  backupCodes: [],
  mfaEnabled: false,
  mfaLockedUntil: 0,
});

function randomBytes(length: number): Uint8Array {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return bytes;
}
function base64Url(bytes: Uint8Array): string {
  return btoa(String.fromCharCode(...bytes))
    .replaceAll("+", "-")
    .replaceAll("/", "_")
    .replaceAll("=", "");
}
function fromBase64(value: string): Uint8Array {
  const binary = atob(value.replaceAll("-", "+").replaceAll("_", "/"));
