    const parsed = new URL(origin);
    const hostAllowed = ["localhost", "127.0.0.1", "[::1]"].includes(parsed.hostname);
    return parsed.protocol === "https:" && hostAllowed && origin === new URL(request.url).origin;
  } catch {
    return false;
  }
