  }

  if (path === "/api/csrf" && request.method === "GET") {
    let session = getSession(request);
    if (!session) session = createSession();
    return json(request, 200, { ok: true, csrf: session.csrf }, { "Set-Cookie": sessionCookie(session.id) });
  }

