   let codes:string[];
   try{codes=await setCodes(a)}finally{a.recoveryCodeOperation=false}
   a.mfaSecret=p.secret;a.pending=undefined;a.mfaEnabled=true;s.failedMfa=0;s.mfaLockedUntil=0;
